201	    public Object complete(JsonParser p, DeserializationContext ctxt, Object bean)
202	        throws IOException
203	    {
204	        for (int i = 0, len = _properties.length; i < len; ++i) {
205	            String typeId = _typeIds[i];
206	            final ExtTypedProperty extProp = _properties[i];
207	            if (typeId == null) {
208	                TokenBuffer tokens = _tokens[i];
209	                // let's allow missing both type and property (may already have been set, too)
210	                // but not just one
211	                if (tokens == null) {
212	                    continue;
213	                }
214	                // [databind#118]: Need to mind natural types, for which no type id
215	                // will be included.
216	                JsonToken t = tokens.firstToken();
217	                if (t.isScalarValue()) { // can't be null as we never store empty buffers
218	                    JsonParser buffered = tokens.asParser(p);
219	                    buffered.nextToken();
220	                    SettableBeanProperty prop = extProp.getProperty();
221	                    Object result = TypeDeserializer.deserializeIfNatural(buffered, ctxt, prop.getType());
222	                    if (result != null) {
223	                        prop.set(bean, result);
224	                        continue;
225	                    }
226	                }
227	                // 26-Oct-2012, tatu: As per [databind#94], must allow use of 'defaultImpl'
228	                if (!extProp.hasDefaultType()) {
229	                    ctxt.reportPropertyInputMismatch(_beanType, extProp.getProperty().getName(),
230	                            "Missing external type id property '%s' (and no 'defaultImpl' specified)",
231	                            extProp.getTypePropertyName());
232	                } else  {
233	                    typeId = extProp.getDefaultTypeId();
234	                    if (typeId == null) {
235	                        ctxt.reportPropertyInputMismatch(_beanType, extProp.getProperty().getName(),
236	"Invalid default type id for property '%s': `null` returned by TypeIdResolver",
237	                                extProp.getTypePropertyName());
238	                    }
239	                }
240	            } else if (_tokens[i] == null) {
241	                SettableBeanProperty prop = extProp.getProperty();
242	
243	                if (prop.isRequired() ||
244	                        ctxt.isEnabled(DeserializationFeature.FAIL_ON_MISSING_EXTERNAL_TYPE_ID_PROPERTY)) {
245	                    ctxt.reportPropertyInputMismatch(bean.getClass(), prop.getName(),
246	                            "Missing property '%s' for external type id '%s'",
247	                            prop.getName(), extProp.getTypePropertyName());
248	                }
249	                return bean;
250	            }
251	            _deserializeAndSet(p, ctxt, bean, i, typeId);
252	        }
253	        return bean;
