341	    protected final Object _deserialize(JsonParser p, DeserializationContext ctxt,
342	            int index, String typeId) throws IOException
343	    {
344	        JsonParser p2 = _tokens[index].asParser(p);
345	        JsonToken t = p2.nextToken();
346	        // 29-Sep-2015, tatu: As per [databind#942], nulls need special support
347	        if (t == JsonToken.VALUE_NULL) {
348	            return null;
349	        }
350	        TokenBuffer merged = ctxt.bufferForInputBuffering(p);
351	        merged.writeStartArray();
352	        merged.writeString(typeId);
353	        merged.copyCurrentStructure(p2);
354	        merged.writeEndArray();
355	
356	        // needs to point to START_OBJECT (or whatever first token is)
357	        JsonParser mp = merged.asParser(p);
358	        mp.nextToken();
359	        return _properties[index].getProperty().deserialize(mp, ctxt);
360	    }
