522	     * This method is needed by some specialized bean deserializers,
523	     * and also called by some {@link #deserializeAndSet} implementations.
524	     *<p>
525	     * Pre-condition is that passed parser must point to the first token
526	     * that should be consumed to produce the value (the only value for
527	     * scalars, multiple for Objects and Arrays).
528	     *<p>
529	     * Note that this method is final for performance reasons: to override
530	     * functionality you must override other methods that call this method;
531	     * this method should also not be called directly unless you really know
532	     * what you are doing (and probably not even then).
533	     */
534	    public final Object deserialize(JsonParser p, DeserializationContext ctxt) throws IOException
535	    {
536	        if (p.hasToken(JsonToken.VALUE_NULL)) {
537	            return _nullProvider.getNullValue(ctxt);
538	        }
539	        if (_valueTypeDeserializer != null) {
540	            return _valueDeserializer.deserializeWithType(p, ctxt, _valueTypeDeserializer);
541	        }
542	        // 04-May-2018, tatu: [databind#2023] Coercion from String (mostly) can give null
543	        Object value =  _valueDeserializer.deserialize(p, ctxt);
544	        if (value == null) {
545	            value = _nullProvider.getNullValue(ctxt);
546	        }
547	        return value;
548	    }
